final class SecurityService{public function report():array{global $wpdb;return array('scope'=>array('site_id'=>get_current_blog_id(),'network_id'=>is_multisite()?get_current_network_id():0),'runtime'=>array('https'=>is_ssl(),'debug_display'=>defined('WP_DEBUG_DISPLAY')&&WP_DEBUG_DISPLAY,'file_editing_disabled'=>defined('DISALLOW_FILE_EDIT')&&DISALLOW_FILE_EDIT,'automatic_updates_disabled'=>defined('AUTOMATIC_UPDATER_DISABLED')&&AUTOMATIC_UPDATER_DISABLED),'login'=>(new LoginAudit())->report(),'roles'=>(new CapabilityAudit())->roles(),'integrations'=>array('wordfence'=>defined('WORDFENCE_VERSION')||class_exists('wordfence'),'aam'=>defined('AAM_VERSION')||class_exists('AAM')),'database'=>array('default_prefix'=>'wp_'===$wpdb->prefix));}public function score(array $r):int{$n=100;if(empty($r['runtime']['https']))$n-=25;if(!empty($r['runtime']['debug_display']))$n-=20;if(empty($r['runtime']['file_editing_disabled']))$n-=15;if(!empty($r['database']['default_prefix']))$n-=5;if(!empty($r['login']['anyone_can_register']))$n-=10;return max(0,$n);}}
